patch:
diff --git a/repro/no-unused-expressions-use-strict.js b/repro/no-unused-expressions-use-strict.js
new file mode 100644
index 0000000..83e356f
--- /dev/null
+++ b/repro/no-unused-expressions-use-strict.js
@@ -0,0 +1,115 @@
+"use strict";
+
+/*
+ * Reproduction: `no-unused-expressions` reports a `'use strict'` directive
+ * (regression in 9.25.0).
+ *
+ * The reporter's project (core-js) lints `packages/core-js*` with the default
+ * parser (Espree) and `ecmaVersion: 3`, with this rule enabled as
+ * `[error, { allowShortCircuit, allowTernary, allowTaggedTemplates }]`.
+ *
+ * Usage (from the repo root):
+ *   node repro/no-unused-expressions-use-strict.js
+ *   node repro/no-unused-expressions-use-strict.js /path/to/node_modules/eslint   # another ESLint install
+ *
+ * Exit code is non-zero while the bug is present, zero when it is not.
+ */
+
+const os = require("node:os");
+const path = require("node:path");
+
+const eslintRoot = process.argv[2]
+	? path.resolve(process.argv[2])
+	: path.resolve(__dirname, "..");
+const { ESLint } = require(eslintRoot);
+const { version } = require(path.join(eslintRoot, "package.json"));
+
+const ruleOptions = {
+	allowShortCircuit: true,
+	allowTernary: true,
+	allowTaggedTemplates: true,
+};
+
+/**
+ * Lints `code` with the rule enabled and returns the rule's messages.
+ * @param {string} code Source text.
+ * @param {string} filePath Pretend path of the file.
+ * @param {number|string} ecmaVersion Parser `ecmaVersion`.
+ * @returns {Promise<object[]>} The `no-unused-expressions` messages.
+ */
+async function lint(code, filePath, ecmaVersion) {
+	const eslint = new ESLint({
+		cwd: os.tmpdir(), // not the repo root: its legacy .eslintignore only adds a warning
+		overrideConfigFile: true,
+		overrideConfig: {
+			files: ["**/*.js"],
+			languageOptions: { ecmaVersion, sourceType: "script" },
+			rules: { "no-unused-expressions": ["error", ruleOptions] },
+		},
+	});
+	const [result] = await eslint.lintText(code, { filePath });
+
+	return result.messages.filter(
+		message => message.ruleId === "no-unused-expressions" || message.fatal,
+	);
+}
+
+// What the report is about: a plain `'use strict'` directive must not be reported.
+const reported = [
+	["ecmaVersion 3, top of file", "'use strict';\nfoo();\n", 3],
+	[
+		"ecmaVersion 3, top of function body",
+		"function f() {\n  'use strict';\n  foo();\n}\n",
+		3,
+	],
+];
+
+// Same code where the directive is already accepted (not part of the pass/fail result).
+const controls = [
+	["ecmaVersion 5, top of file", "'use strict';\nfoo();\n", 5],
+	["ecmaVersion latest, top of file", "'use strict';\nfoo();\n", "latest"],
+];
+
+(async () => {
+	console.log(`ESLint ${version} (${eslintRoot})`);
+
+	for (const [name, code, ecmaVersion] of controls) {
+		const messages = await lint(
+			code,
+			"packages/core-js/modules/x.js",
+			ecmaVersion,
+		);
+
+		console.log(`  [control] ${name}: ${messages.length} message(s)`);
+	}
+
+	let failed = false;
+
+	for (const [name, code, ecmaVersion] of reported) {
+		const messages = await lint(
+			code,
+			"packages/core-js/modules/x.js",
+			ecmaVersion,
+		);
+
+		if (messages.length) {
+			failed = true;
+			for (const m of messages) {
+				console.log(
+					`  [FAIL] ${name}: ${m.line}:${m.column} ${m.message}`,
+				);
+			}
+		} else {
+			console.log(`  [ok]   ${name}: no messages`);
+		}
+	}
+
+	if (failed) {
+		console.log(
+			"\nBUG PRESENT: `no-unused-expressions` reported a 'use strict' directive.",
+		);
+		process.exitCode = 1;
+	} else {
+		console.log("\nOK: 'use strict' directives are not reported.");
+	}
+})();
